//! One-shot prospective paper observer. Reads existing evidence only: no HTTP
//! client, credential provider, execution authority or original-wallet writer.
use crate::{Result,SourcePin,clock,need,publication::Publisher,storage::{OwnerLock,OwnedJournal,atomic_json,sha,journal_rows}};
use baal_portfolio_engine::{PortfolioEngine,RECEIPT_BASELINE_MODE,digest,js_stringify};
use serde::{Serialize,Deserialize};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{fs::{self,File},io::{Read,BufRead,BufReader,Seek,SeekFrom},path::{Path,PathBuf},collections::BTreeSet};

#[derive(Clone,Serialize,Deserialize)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct ObserverConfig {
 pub cohort_dir:PathBuf,pub bank_path:PathBuf,pub bank_file_hash:String,pub bank_hash:String,
 pub public_source_path:PathBuf,pub account_source_path:PathBuf,pub account_universe_hash:String,
 #[serde(default)]pub stop_paths:Vec<PathBuf>,#[serde(default)]pub code_pins:Vec<SourcePin>,
 #[serde(default)]pub entry_enabled:bool,#[serde(default)]pub entry_drain_path:Option<PathBuf>,
}
fn hex(s:&str)->bool{s.len()==64&&s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))}
fn complete_bytes(path:&Path)->Result<u64>{let mut f=File::open(path).map_err(|_|"OBSERVER_INPUT_UNAVAILABLE")?;let size=f.metadata().map_err(|_|"OBSERVER_INPUT_UNAVAILABLE")?.len();let mut cursor=size;let mut scanned=0;let mut b=vec![0u8;65536];while cursor>0{let n=(cursor.min(b.len() as u64)) as usize;cursor-=n as u64;f.seek(SeekFrom::Start(cursor)).map_err(|_|"OBSERVER_INPUT_READ")?;f.read_exact(&mut b[..n]).map_err(|_|"OBSERVER_INPUT_READ")?;if let Some(at)=b[..n].iter().rposition(|b|*b==b'\n'){return Ok(cursor+at as u64+1);}scanned+=n;need(scanned<=1024*1024,"OBSERVER_OVERSIZE_PARTIAL_RECORD")?;}Ok(0)}
fn prefix_sha(path:&Path,end:u64)->Result<String>{let file=File::open(path).map_err(|_|"OBSERVER_INPUT_UNAVAILABLE")?;need(file.metadata().map_err(|_|"OBSERVER_INPUT_READ")?.len()>=end,"OBSERVER_INPUT_TRUNCATED")?;let mut r=file.take(end);let mut h=Sha256::new();let mut buf=[0u8;65536];loop{let n=r.read(&mut buf).map_err(|_|"OBSERVER_INPUT_READ")?;if n==0{break;}h.update(&buf[..n]);}Ok(format!("{:x}",h.finalize()))}
struct SourceRows {reader:BufReader<std::io::Take<File>>,offset:u64}
impl SourceRows {
 fn open(path:&Path,start:u64,end:u64)->Result<Self>{need(start<=end,"OBSERVER_INPUT_TRUNCATED")?;let mut f=File::open(path).map_err(|_|"OBSERVER_INPUT_UNAVAILABLE")?;f.seek(SeekFrom::Start(start)).map_err(|_|"OBSERVER_INPUT_READ")?;Ok(Self{reader:BufReader::new(f.take(end-start)),offset:start})}
 fn next(&mut self)->Result<Option<Value>>{let mut b=Vec::new();let n=(&mut self.reader).take(1024*1024+2).read_until(b'\n',&mut b).map_err(|_|"OBSERVER_INPUT_READ")?;if n==0{return Ok(None);}need(n<=1024*1024&&b.last()==Some(&b'\n'),"OBSERVER_INCOMPLETE_OR_LARGE_RECORD")?;self.offset+=n as u64;serde_json::from_slice(&b).map(Some).map_err(|_|"OBSERVER_INPUT_JSON".into())}
}
#[derive(Clone)]struct AccountRecord{sequence:u64,hash:String,known_at:i64,snapshot:Value}
struct Accounts{rows:Vec<AccountRecord>,bytes:u64,sha:String}
impl Accounts{
 fn load(config:&ObserverConfig,bank:&Value)->Result<Self>{let end=complete_bytes(&config.account_source_path)?;let mut reader=SourceRows::open(&config.account_source_path,0,end)?;let mut rows=Vec::new();let mut sequence=0;let mut previous=String::new();let mut last_known=0;let mut last_positions=0;let mut last_orders=0;
  while let Some(row)=reader.next()?{let mut body=row.clone();let hash=body["hash"].as_str().ok_or("OBSERVER_ACCOUNT_HASH")?.to_owned();body.as_object_mut().ok_or("OBSERVER_ACCOUNT_RECORD")?.shift_remove("hash");sequence+=1;
   need(row["sequence"]==sequence&&row["previous"]==previous&&digest(&body)==hash&&row["state"].is_null()&&row["event"]["type"]=="market_account_eligibility","OBSERVER_ACCOUNT_CHAIN")?;
   let snapshot=&row["event"]["snapshot"];let known=clock(row["at"].as_str().ok_or("OBSERVER_ACCOUNT_CLOCK")?)?;let p=clock(snapshot["positionsAt"].as_str().ok_or("OBSERVER_ACCOUNT_CLOCK")?)?;let o=clock(snapshot["ordersAt"].as_str().ok_or("OBSERVER_ACCOUNT_CLOCK")?)?;
   need(snapshot.as_object().is_some_and(|m|m.len()==7)&&snapshot["tournamentId"]==bank["universe"]["tournamentId"]&&snapshot["universeHash"]==config.account_universe_hash&&snapshot["complete"]==true&&p<=o&&o<=known&&known>=last_known&&p>=last_positions&&o>=last_orders&&clock(snapshot["expiresAt"].as_str().ok_or("OBSERVER_ACCOUNT_CLOCK")?)?==p.min(o)+20000,"OBSERVER_ACCOUNT_SCOPE_OR_CLOCK")?;
   let markets=snapshot["excludedMarketIds"].as_array().ok_or("OBSERVER_ACCOUNT_EXCLUSIONS")?;let mut seen=BTreeSet::new();for m in markets{let id=m.as_str().ok_or("OBSERVER_ACCOUNT_EXCLUSIONS")?;need(seen.insert(id)&&bank["universe"]["exchanges"].as_array().ok_or("OBSERVER_SCOPE")?.iter().any(|e|e["marketId"]==id),"OBSERVER_ACCOUNT_EXCLUSIONS")?;}
   rows.push(AccountRecord{sequence,hash:hash.clone(),known_at:known,snapshot:snapshot.clone()});previous=hash;last_known=known;last_positions=p;last_orders=o;
  }Ok(Self{rows,bytes:end,sha:prefix_sha(&config.account_source_path,end)?})
 }
 fn at(&self,row:&Value,available:&str,bank:&Value)->Result<Option<(Value,Value)>>{
  if row["kind"]!="book"{return Ok(None);}let b=&row["payload"]["book"];let request=clock(b["requestStartedAt"].as_str().ok_or("OBSERVER_BOOK_CLOCK")?)?;let now=clock(available)?;
  let found=self.rows.partition_point(|r|r.known_at<=request.min(now));let Some(record)=found.checked_sub(1).and_then(|i|self.rows.get(i))else{return Ok(None);};
  let excluded=record.snapshot["excludedMarketIds"].as_array().unwrap();let mut ids=bank["universe"]["exchanges"].as_array().unwrap().iter().filter(|e|excluded.contains(&e["marketId"])).map(|e|e["exchangeId"].as_str().map(str::to_string).ok_or("OBSERVER_SCOPE")).collect::<std::result::Result<Vec<_>,_>>()?;ids.sort_by_key(|s|s.parse::<u64>().unwrap_or(u64::MAX));
  Ok(Some((json!({"schemaVersion":1,"positionsAt":record.snapshot["positionsAt"],"ordersAt":record.snapshot["ordersAt"],"excludedExchangeIds":ids}),json!({"sequence":record.sequence,"hash":record.hash,"knownAt":record.known_at,"sourceBytes":self.bytes,"sourceSha256":self.sha}))))
 }
}

pub struct Observer{config:ObserverConfig,bank:Value,engine:PortfolioEngine,publisher:Publisher,journal:OwnedJournal,owner:OwnerLock,source_bytes:u64,source_sha:String,sticky_drain:bool,failed:bool,last_batch:Option<Value>,configuration_hash:String}
impl Observer {
 pub fn open(config:ObserverConfig)->Result<Self>{
  need(config.cohort_dir.is_absolute()&&config.bank_path.is_absolute()&&config.public_source_path.is_absolute()&&config.account_source_path.is_absolute()&&config.stop_paths.iter().all(|p|p.is_absolute())&&config.entry_drain_path.as_ref().is_none_or(|p|p.is_absolute())&&hex(&config.bank_file_hash)&&hex(&config.bank_hash)&&hex(&config.account_universe_hash),"OBSERVER_CONFIGURATION")?;
  need(config.bank_path.parent()==Some(config.cohort_dir.as_path())&&config.cohort_dir.parent().and_then(Path::file_name).is_some_and(|n|n=="settlement-portfolio-v3-cohorts")&&config.public_source_path.file_name().is_some_and(|n|n=="public-books.jsonl")&&config.account_source_path.file_name().is_some_and(|n|n=="account-eligibility.jsonl"),"OBSERVER_SEPARATE_V3_SCOPE_REQUIRED")?;
  let bank_bytes=fs::read(&config.bank_path).map_err(|_|"OBSERVER_BANK_UNAVAILABLE")?;need(sha(&bank_bytes)==config.bank_file_hash,"OBSERVER_BANK_FILE_PIN")?;let bank:Value=serde_json::from_slice(&bank_bytes).map_err(|_|"OBSERVER_BANK_JSON")?;need(bank["schemaVersion"]==3&&bank["mode"]==RECEIPT_BASELINE_MODE&&digest(&bank)==config.bank_hash,"OBSERVER_V3_BANK_REQUIRED")?;
  need(bank["codeIdentity"]["language"]=="Rust"&&bank["codeIdentity"]["engineHash"]==baal_portfolio_engine::engine_hash()&&!config.code_pins.is_empty(),"OBSERVER_COMPILED_FROZEN_ENGINE_REQUIRED")?;
  let binary=bank["codeIdentity"]["binaryHash"].as_str().ok_or("OBSERVER_BINARY_PIN")?;need(hex(binary)&&config.code_pins.iter().any(|p|p.sha256==binary),"OBSERVER_BINARY_PIN")?;
  for hash in bank["codeIdentity"]["sources"].as_object().ok_or("OBSERVER_FROZEN_SOURCE_PINS")?.values(){need(hash.as_str().is_some_and(|h|hex(h)&&config.code_pins.iter().any(|p|p.sha256==h)),"OBSERVER_FROZEN_SOURCE_PINS")?;}
  for pin in &config.code_pins{need(pin.path.is_absolute()&&hex(&pin.sha256)&&sha(&fs::read(&pin.path).map_err(|_|"OBSERVER_CODE_PIN_UNAVAILABLE")?)==pin.sha256,"OBSERVER_CODE_PIN_CHANGED")?;}
  let mut stops=config.stop_paths.clone();stops.push(config.cohort_dir.join("STOP"));need(!stops.iter().any(|p|p.exists()),"OBSERVER_STOPPED")?;let owner=OwnerLock::acquire(&config.cohort_dir.join("observer.lock"))?;let mut engine=PortfolioEngine::new(bank.clone())?;
  let initial_bytes=bank["sourcePrefixBytes"].as_u64().ok_or("OBSERVER_BANK_PREFIX")?;let initial_sha=bank["sourcePrefixHash"].as_str().ok_or("OBSERVER_BANK_PREFIX")?.to_owned();let mut publisher=Publisher::from_verified_prefix(&config.public_source_path,initial_bytes,&initial_sha,&bank["universe"])?;
  need(publisher.status()["sequence"]==bank["sourcePrefixSequence"]&&publisher.status()["hash"]==bank["sourcePrefixJournalHash"]&&clock(publisher.status()["lastAt"].as_str().ok_or("OBSERVER_PREFIX_CLOCK")?)?<=clock(bank["cutoff"].as_str().ok_or("OBSERVER_BANK_CLOCK")?)?,"OBSERVER_BANK_SOURCE_FRONTIER")?;
  let configuration_hash=digest(&json!({"bankPath":config.bank_path,"bankFileHash":config.bank_file_hash,"bankHash":config.bank_hash,"publicSourcePath":config.public_source_path,"accountSourcePath":config.account_source_path,"accountUniverseHash":config.account_universe_hash,"codePins":config.code_pins,"stopPaths":config.stop_paths,"entryDrainPath":config.entry_drain_path}));
  let path=config.cohort_dir.join("native-observer.jsonl");let mut journal=OwnedJournal::open(&path,owner.token(),&stops)?;let mut source_bytes=initial_bytes;let mut source_sha=initial_sha;let mut sticky_drain=false;let mut last_batch=None;
  let accounts=Accounts::load(&config,&bank)?;let source_end=complete_bytes(&config.public_source_path)?;let mut source=SourceRows::open(&config.public_source_path,initial_bytes,source_end)?;
  if journal.status()["sequence"].as_u64().unwrap_or(0)>0{journal_rows(&path,|record|{let event=&record["event"];need(event["configurationHash"]==configuration_hash,"OBSERVER_IMMUTABLE_INPUTS_CHANGED")?;
    if event["kind"]=="genesis"{need(record["sequence"]==1&&record["state"]["sourceBytes"]==source_bytes&&record["state"]["sourceSha256"]==source_sha&&digest(&record["state"]["paper"])==digest(engine.state()),"OBSERVER_GENESIS")?;sticky_drain|=record["state"]["entryDraining"]==true;}
    else if event["kind"]=="operator_entry_drain"{sticky_drain=true;}
    else{need(event["kind"]=="native_observer_batch","OBSERVER_JOURNAL_EVENT")?;let at=event["availableAt"].as_str().ok_or("OBSERVER_REPLAY_CLOCK")?;let account_bytes=event["accountPrefixBytes"].as_u64().ok_or("OBSERVER_ACCOUNT_PREFIX_PIN")?;need(account_bytes<=accounts.bytes&&prefix_sha(&config.account_source_path,account_bytes)?==event["accountPrefixSha256"],"OBSERVER_ACCOUNT_PREFIX_CHANGED")?;
     for observed in event["observations"].as_array().ok_or("OBSERVER_REPLAY_ROWS")?{let actual=source.next()?.ok_or("OBSERVER_SOURCE_TRUNCATED")?;need(js_stringify(&actual)==js_stringify(&observed["row"]),"OBSERVER_ORIGINAL_SOURCE_ROW_CHANGED")?;publisher.apply_record(&actual)?;let selected=accounts.at(&actual,at,&bank)?;let (account,evidence)=selected.unwrap_or((Value::Null,Value::Null));need(observed["accountEligibility"]==account&&evidence["sequence"]==observed["accountEvidence"]["sequence"]&&evidence["hash"]==observed["accountEvidence"]["hash"],"OBSERVER_CAUSAL_ACCOUNT_EVIDENCE_CHANGED")?;engine.apply_with_entry_permission(&actual,at,if account.is_null(){None}else{Some(&account)},event["allowNewEntries"]==true)?;}
     source_bytes=source.offset;source_sha=record["state"]["sourceSha256"].as_str().ok_or("OBSERVER_SOURCE_PIN")?.into();need(record["state"]["sourceBytes"]==source_bytes&&record["state"]["sourceSequence"]==publisher.status()["sequence"]&&record["state"]["sourceHash"]==publisher.status()["hash"]&&digest(&record["state"]["paper"])==digest(engine.state()),"OBSERVER_EXACT_REPLAY_STATE")?;sticky_drain|=record["state"]["entryDraining"]==true;last_batch=Some(event.clone());
    }Ok(())})?;need(prefix_sha(&config.public_source_path,source_bytes)?==source_sha,"OBSERVER_SOURCE_PREFIX_CHANGED")?;
  }else{sticky_drain=!config.entry_enabled||config.entry_drain_path.as_ref().is_some_and(|p|p.exists());journal.commit(json!({"paper":engine.state(),"sourceBytes":source_bytes,"sourceSha256":source_sha,"sourceSequence":publisher.status()["sequence"],"sourceHash":publisher.status()["hash"],"entryDraining":sticky_drain}),json!({"kind":"genesis","configurationHash":configuration_hash,"bankHash":config.bank_hash,"cutoff":bank["cutoff"],"clockModel":"actual_native_observer_batch_receipt"}),bank["cutoff"].as_str().unwrap())?;}
  let out=Self{config,bank,engine,publisher,journal,owner,source_bytes,source_sha,sticky_drain,failed:false,last_batch,configuration_hash};out.guard()?;Ok(out)
 }
 fn guard(&self)->Result<()>{self.owner.check()?;need(!self.failed&&!self.config.cohort_dir.join("STOP").exists()&&!self.config.stop_paths.iter().any(|p|p.exists()),"OBSERVER_STOPPED_OR_FAILED")?;need(sha(&fs::read(&self.config.bank_path).map_err(|_|"OBSERVER_BANK_UNAVAILABLE")?)==self.config.bank_file_hash,"OBSERVER_BANK_CHANGED")?;for pin in &self.config.code_pins{need(pin.path.is_absolute()&&hex(&pin.sha256)&&sha(&fs::read(&pin.path).map_err(|_|"OBSERVER_CODE_PIN_UNAVAILABLE")?)==pin.sha256,"OBSERVER_CODE_PIN_CHANGED")?;}Ok(())}
 pub fn consume_once(&mut self,available_at:&str,maximum_rows:usize)->Result<Value>{let result=self.consume_inner(available_at,maximum_rows);if result.is_err(){self.failed=true;}result}
 fn consume_inner(&mut self,available_at:&str,maximum_rows:usize)->Result<Value>{
  self.guard()?;let now=clock(available_at)?;need(maximum_rows>0&&maximum_rows<=4096&&now>=clock(self.engine.state()["lastAvailableAt"].as_str().ok_or("OBSERVER_WALLET_CLOCK")?)?,"OBSERVER_CONSUMER_CLOCK_OR_BOUND")?;
  need(prefix_sha(&self.config.public_source_path,self.source_bytes)?==self.source_sha,"OBSERVER_SOURCE_PREFIX_CHANGED")?;let accounts=Accounts::load(&self.config,&self.bank)?;
  let drained=!self.config.entry_enabled||self.config.entry_drain_path.as_ref().is_some_and(|p|p.exists());if drained&&!self.sticky_drain{self.sticky_drain=true;self.journal.commit(self.checkpoint(),json!({"kind":"operator_entry_drain","configurationHash":self.configuration_hash,"availableAt":available_at}),available_at)?;}
  let end=complete_bytes(&self.config.public_source_path)?;let mut source=SourceRows::open(&self.config.public_source_path,self.source_bytes,end)?;let mut observations=Vec::new();let mut consumed_offset=self.source_bytes;
  while observations.len()<maximum_rows{let Some(row)=source.next()?else{break};if clock(row["at"].as_str().ok_or("OBSERVER_PUBLIC_CLOCK")?)?>now{break;}self.publisher.apply_record(&row)?;let selected=accounts.at(&row,available_at,&self.bank)?;let(account,evidence)=selected.unwrap_or((Value::Null,Value::Null));self.engine.apply_with_entry_permission(&row,available_at,if account.is_null(){None}else{Some(&account)},!self.sticky_drain)?;observations.push(json!({"row":row,"accountEligibility":account,"accountEvidence":evidence}));consumed_offset=source.offset;}
  if !observations.is_empty(){self.source_bytes=consumed_offset;self.source_sha=prefix_sha(&self.config.public_source_path,self.source_bytes)?;let event=json!({"kind":"native_observer_batch","configurationHash":self.configuration_hash,"availableAt":available_at,"clockModel":"actual_native_observer_batch_receipt","allowNewEntries":!self.sticky_drain,"observations":observations,"accountPrefixBytes":accounts.bytes,"accountPrefixSha256":accounts.sha});self.journal.commit(self.checkpoint(),event.clone(),available_at)?;self.last_batch=Some(event);}
  self.guard()?;let report=self.status(available_at)?;atomic_json(&self.config.cohort_dir.join("stats.json"),&report)?;Ok(json!({"cohort":self.bank["name"],"bankHash":self.config.bank_hash,"consumedRows":observations.len(),"journalSequence":self.journal.status()["sequence"],"sourceSequence":self.publisher.status()["sequence"],"stateHash":digest(self.engine.state()),"networkRequests":0,"competitionOrders":0,"executionAuthority":false,"status":"completed_batch"}))
 }
 fn checkpoint(&self)->Value{json!({"paper":self.engine.state(),"sourceBytes":self.source_bytes,"sourceSha256":self.source_sha,"sourceSequence":self.publisher.status()["sequence"],"sourceHash":self.publisher.status()["hash"],"entryDraining":self.sticky_drain})}
 pub fn status(&self,at:&str)->Result<Value>{let mut report=self.engine.report(at)?;let mut quote_times=json!({});if let Some(books)=self.engine.state()["books"].as_object(){for(id,b)in books{quote_times[id]=json!({"requestStartedAt":b["requestStartedAt"],"receivedAt":b["receivedAt"],"availableAt":b["availableAt"]});}}report["observer"]=json!({"mode":"native_one_shot_source_observer","status":if self.failed{"failed"}else{"completed_batch"},"pid":std::process::id(),"persistentWorker":false,"clockModel":"actual_native_observer_batch_receipt","sourceBytes":self.source_bytes,"sourceSha256":self.source_sha,"sourceSequence":self.publisher.status()["sequence"],"sourceHash":self.publisher.status()["hash"],"sourceClosed":self.publisher.status()["closed"],"journalSequence":self.journal.status()["sequence"],"journalHash":self.journal.status()["tailHash"],"entryDraining":self.sticky_drain,"lastAvailableAt":self.engine.state()["lastAvailableAt"],"bankFileHash":self.config.bank_file_hash,"configurationHash":self.configuration_hash,"lastBatchRows":self.last_batch.as_ref().and_then(|e|e["observations"].as_array()).map(Vec::len).unwrap_or(0),"quoteTimes":quote_times,"accountClockPolicy":"known_before_original_request_then_actual_consumer_freshness","networkRequests":0,"competitionOrders":0,"executionAuthority":false});Ok(report)}
}

